    /**
     * Logout Any Active Session
     */
    $(document).on("click", ".logoutsession", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        $.ajax({
            type: "GET",
            url: obj.attr('href'),
            data: {},
            dataType: 'JSON',
            global:false,
            success: function (result) {
                if (result.status == '1') {
                    alert(result.message);
                    obj.closest('td').html('');
                } else {
                    alert(result.message);
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });

    /**
     * Logout Session By User
     */
    $(document).on("click", ".logoutall", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var obj = $(this);
        $.ajax({
            type: "GET",
            url: obj.attr('href'),
            data: {},
            dataType: 'JSON',
            global:false,
            success: function (result) {
                if (result.status == '1') {
                    alert(result.message);
                    reload();
                } else {
                    alert(result.message);
                }
            },
            error: function (data) {
                console.log('An error occurred.');
                console.log(data);
            }
        });
    });


    $('#ajaxModal').on('hidden.bs.modal', function (e) {
        if($(this).attr('data-action-close') == 'reload'){
            reload();
        } else if($(this).attr('data-action-close') == 'gridreload'){
            gridReload();
        }

    })

    /**
     * Load ajax modal on click event
     */
    $(document).on("click", "a.ajaxmodal", function (e) {
        e.preventDefault();
        var obj = $(this),
            link = obj.attr('href'),
            modal = $('#ajaxModal');


        if(obj.data('action-close')) {
            modal.attr('data-action-close', obj.data('action-close'));
        } else {
            modal.attr('data-action-close', 'false');
        }

        //var loadedlink = modal.data('link');
        //if(link != loadedlink) {
            modal.data('link',link);
            ///////////
            $.ajax({
                type: "GET",
                url: link,
                data: {}, // serializes the form's elements.
                dataType:'html',
                global:false,
                success: function(data)
                {
                    modal.modal('show');
                    modal.find('.modal-content').html(data);
                    if(obj.data('redirect')){
                        modal.find('form').attr('data-redirect',obj.data('redirect'));
                    }
                    if(obj.data('settomodal')) {
                        var settomodal = JSON.parse(obj.attr('data-settomodal'));
                        for (key in settomodal) {
                            modal.find('select[name='+key+']').attr('data-value',settomodal[key]);                          modal.find('input[name='+key+']').val(settomodal[key]);
                            modal.find('input[type=checkbox][name='+key+']').attr('data-check',settomodal[key]);
                        }
                        $(".chosen").trigger('chosen:updated');
                    }

                    loadDefaultValue();
                    if(obj.data('target')) {
                        modal.find('form').attr('data-target',obj.data('target'));
                        // modal.find('form').attr('data-selected',obj.data('selected'));
                    }
                },
                error: function (data, textStatus, jqXHR) {
                    alert(jqXHR);
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
            ///////////
        //}
        //modal.modal('show');
    });

    $(document).on("submit", "form.ajax-submit-modal", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var url = form.attr('action');
        var method = form.attr('method');
        var modal = form.closest('.modal');
        var where = target = options = '';
        var ind, inds;


        form.find(':disabled').prop('disabled', false).addClass('disabled');
        $.ajax({
            type: method,
            url: url,
            data: form.serialize(), // serializes the form's elements.
            dataType: 'JSON',
            success: function (result) {
                form.find('.disabled').prop('disabled', true);
                if (result.status == '1') {
                    if (form.data('target')) {
                        target = form.data('target');
                        targets = target.split(',');

                        for(i=0; i < targets.length; i++){
                            loadOptions(targets[i],result.data.id);
                        }
                        $(".chosen").trigger('chosen:updated');
                        modal.modal('hide');
                    } else {
                        alert(result.message);
                        if (form.data('redirect')) {
                            if (form.data('redirect') == '' || form.data('redirect') == 'reload') {
                                gridReload();
                            } else {
                                redirect(form.data('redirect'));
                            }
                        }
                    }
                } else {
                    alert(result.message);
                }
            },
            error: function (data) {
                form.find('.disabled').prop('disabled', true);
                console.log('An error occurred.');
                console.log(data);
            }
        });

    });



   	$(document).on("submit", "form.ajax-submit-body", function (e) {
	    e.preventDefault(); // avoid to execute the actual submit of the form.
	    var form = $(this);
	    var url = form.attr('action');
        var redirectto = form.data('redirect');
        //alert(redirect);
	    $.ajax({
           type: "POST",
           url: url,
           data: form.serialize(), // serializes the form's elements.
           dataType:'JSON',
           success: function(result)
           {
               alert(result.message);
               if(result.status == '1') {
                   if (typeof redirectto !== 'undefined') {
                       switch (redirectto) {
                           case('reload'):
                               reload();
                               break;
                           case('reset'):
                               formReset(form);
                               break;
                           default:
                               redirect(redirectto);
                       }
                   }
               }
           },
           error: function (data) {
                form.find('.disabled').prop('disabled', true);
                console.log('An error occurred.');
                console.log(data);
            }
         });
	});



    $(document).on("submit", "form#ajax-submit-modal-payment", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var redirectto = form.attr('data-redirect');
        var balanced = false;
        if(form.data('balanced') == 'true' || form.data('balanced') == true){
            balanced = true;
        }
        var url = form.attr('action');
        var netprice = parseInt(form.find('#netprice').text());
        var paymentamount = parseInt(form.find('#total-payment-amount').text());
        if((netprice > paymentamount) && (balanced)){
            alert('PAYMENT AMOUNT IS EQUAL TO BILL AMOUNT.');
        } else {
           $.ajax({
           type: "POST",
           url: url,
           data: form.serialize(), // serializes the form's elements.
           dataType:'JSON',
           success: function(result)
           {
               if(result.status == '1') {
                   popupWindow(result.link,result.refid);
                   if (typeof redirectto !== typeof undefined && redirectto !== false) {
                       redirect(redirectto);
                   } else {
                       reload();
                   }

                   closeLoader();
                    // alert(result.message);
                    // reload();
               } else {
                    alert(result.message);
               }
           },
           error: function (data) {
                form.find('.disabled').prop('disabled', true);
                console.log('An error occurred.');
                console.log(data);
            }
         });
         }
         return false;
	});


///Here///
    $(document).on("submit", "form#ajax-submit-modal-payment-reservation", function (e) {
        e.preventDefault(); // avoid to execute the actual submit of the form.
        var form = $(this);
        var redirectto = form.attr('data-redirect');
        var balanced = false;
        if(form.data('balanced') == 'true' || form.data('balanced') == true){
            balanced = true;
        }
        var url = form.attr('action');
        var netprice = parseInt(form.find('#netprice').text());
        var paymentamount = parseInt(form.find('#total-payment-amount').text());
        if((netprice > paymentamount) && (balanced)){
            alert('PAYMENT AMOUNT IS EQUAL TO BILL AMOUNT.');
        } else {
            $.ajax({
                type: "POST",
                url: url,
                data: form.serialize(), // serializes the form's elements.
                dataType:'JSON',
                success: function(result)
                {
                    if(result.status == '1') {
                        var reportaction = 'printreport';
                        if(form.find('input[name=reportaction]').length > 0){
                            reportaction = form.find('input[name=reportaction]:checked').val();
                        }
                        //alert(reportaction)
                        if(reportaction == 'printreport' || reportaction == 'printreceipt' || reportaction == 'printconfirmation') {
                            popupWindow(result.link, result.refid);
                            if (typeof redirectto !== typeof undefined && redirectto !== false) {
                                redirect(redirectto);
                            } else {
                                reload();
                            }
                        } else {
                            if(reportaction == 'emailreport' || reportaction == 'emailreceipt' || reportaction == 'emailconfirmation') {
                                var modal = $('#ajaxModal');
                                modal.attr('data-action-close', 'reload');
                                modal.find('.modal-content').html(result.emailform);
                                modal.modal('show');
                            } else {
                                if (typeof redirectto !== typeof undefined && redirectto !== false) {
                                    redirect(redirectto);
                                } else {
                                    reload();
                                }
                            }
                        }
                        closeLoader();
                        // alert(result.message);
                        // reload();
                    } else {
                        alert(result.message);
                    }
                },
                error: function (data) {
                    form.find('.disabled').prop('disabled', true);
                    console.log('An error occurred.');
                    console.log(data);
                }
            });
        }
        return false;
    });


	$(document).on("submit", "form.ajax-submit", function (e) {
	    e.preventDefault(); // avoid to execute the actual submit of the form.
	    var form = $(this);
	    var url = form.attr('action');
        var method = form.attr('method');
	    var modal = form.closest('.modal');

	    //form.find(':disabled').removeAttr('disabled').addClass('disabled');
	    form.find(':disabled').prop('disabled', false).addClass('disabled');
	    $.ajax({
	           type: method,
	           url: url,
	           data: form.serialize(), // serializes the form's elements.
	           dataType:'JSON',
	           success: function(result)
	           {
	           	   form.find('.disabled').prop('disabled', true);
	               if(result.status == '1') {
	               		if(form.data('target')) {
	               			var target = $(form.data('target'));
	               			if(form.data('selected') == true || form.data('selected') == 'true') {
                                //$("#yourSelect option[value='yourValue']").length > 0;
                               // alert(target.find("option[value='" + result.data.id + "']").text());
                                if (target.find("option[value='" + result.data.id + "']").length > 0) {
                                    target.val(result.data.id).trigger('chosen:updated');
                                } else {
                                    target.append($('<option></option>')
                                    .val(result.data.id)
                                    .attr('selected', 'selected')
                                    .html(result.data.name)).trigger('chosen:updated');
                                }
	               			} else {
	               				target.append($('<option></option>')
						        .val(result.data.id)
						        .html(result.data.name)).trigger('chosen:updated');
	               			}
	               			modal.modal('hide');
	               		}
	               		alert(result.message);
	               		if(form.data('redirect')){
	               			if(form.data('redirect') == '' || form.data('redirect') == 'reload'){
								gridReload();
							} else {
								redirect(form.data('redirect'));
							}
						}
                       if(form.data('submit')){
                           if(form.data('submit') == 'close'){
                               modal.modal('hide');
                           }
                       }
	               } else {
	               		alert(result.message);
	               }
	           },
                error: function(jqXHR, textStatus, errorThrown) {
	               switch(jqXHR.status){
                       case 422:
                           alert('Please Enter or data properly');
                           break;
                       default:
                           alert('Server Error');
                   }
                    // alert(jqXHR.status);
                    // alert(textStatus);
                    // alert(errorThrown);
                }
	         });
	});

	$(document).on("click", ".ajax-action", function (e) {
		e.preventDefault(); // avoid to execute the actual submit of the form.
		var obj = $(this);
		var url = obj.attr('href');
		var redirect = obj.data('redirect');

		$.ajax({
			type: "GET",
			url: url,
			data:{},
			dataType:'JSON',
			success: function(result)
			{
				if(result.status == '1') {
					alert(result.message);
					if(obj.data('redirect')){
						redirect(obj.data('redirect'));
					} else {
						gridReload();
					}
				} else {
					alert(result.message);
				}
			},
			error: function (data) {
				console.log('An error occurred.');
				console.log(data);
			}
		});
	});

