    $(document).on("change", ".calculateservicechargevat", function (e) {
   	    var obj = $(this);
            var form = $(this).closest('form');
            var servicecharge = form.find('input[type=checkbox][name=servicecharge_per]');
            var vat = form.find('input[type=checkbox][name=vat_per]');
            var price = form.find('#price').val();
            var servicecharge_per = 0;
            var vat_per = 0;
            if(servicecharge.is(':checked')) {
                servicecharge_per = servicecharge.val();
            }
            if(vat.is(':checked')) {
                vat_per = vat.val();
            }
            var addServicecharge = applyCharge(price,servicecharge_per);
            var addVat = applyCharge(addServicecharge.sum,vat_per);
            form.find('#priceaftercharge').html(addVat.sum);
            salesDiscountCalcultion('per');
   	});


	$(document).on("change", ".checkall", function (e) {
		var obj = $(this);
		var form = obj.closest('form');
		if(obj.is(':checked')){
			form.find('.checkindividual').each(function(i) {
				$(this).prop('checked',true);
			});
		} else {
			form.find('.checkindividual').each(function(i) {
				$(this).prop('checked', false);
			});
		}
	});


	$(document).on("change", ".checkindividual", function (e) {
		var obj = $(this);
		var form = obj.closest('form');
		var allchecked = true;
		form.find('.checkindividual').each(function(i) {
			if(!$(this).is(':checked')){
				allchecked = false;
			}
		});

		if(allchecked){
			form.find('.checkall').prop('checked',true);
		} else {
			form.find('.checkall').prop('checked',false);
		}
	});


    $(document).on("change", ".checkpermissionall", function (e) {
        var obj = $(this);
        var block = obj.closest('.check-block');
        if(obj.is(':checked')){
            block.find('.checkpermissionindividual').each(function(i) {
                $(this).prop('checked',true);
            });
        } else {
            block.find('.checkpermissionindividual').each(function(i) {
                $(this).prop('checked', false);
            });
        }
    });


    $(document).on("change", ".checkpermissionindividual", function (e) {
        var obj = $(this);
        var block = obj.closest('.check-block');
        var allchecked = true;
        block.find('.checkpermissionindividual').each(function(i) {
            if($(this).is(":not(:checked)")){
                allchecked = false;
            }
        });
        if(allchecked){
            block.find('.checkpermissionall').prop('checked',true);
        } else {
            block.find('.checkpermissionall').prop('checked',false);
        }
    });


